# Builds the release binary, the portable zip and (when Inno Setup 6 is installed) the installer.
# Usage:  powershell -ExecutionPolicy Bypass -File dist\package.ps1
$ErrorActionPreference = "Stop"
$root = Split-Path -Parent (Split-Path -Parent $MyInvocation.MyCommand.Path)
Set-Location $root
cargo build --release
if ($LASTEXITCODE -ne 0) { throw "cargo build failed" }
$version = (Select-String -Path Cargo.toml -Pattern '^version\s*=\s*"([^"]+)"' | Select-Object -First 1).Matches[0].Groups[1].Value

# Portable zip
$stage = Join-Path $root "dist\stage"
if (Test-Path $stage) { Remove-Item -Recurse -Force $stage }
New-Item -ItemType Directory -Force $stage | Out-Null
Copy-Item "target\release\winbend.exe" $stage
Copy-Item "dist\README.txt" $stage
Copy-Item "LICENSE" $stage
$zip = Join-Path $root "dist\WinBend-$version-win64.zip"
if (Test-Path $zip) { Remove-Item -Force $zip }
Compress-Archive -Path "$stage\*" -DestinationPath $zip
Remove-Item -Recurse -Force $stage
Write-Host "wrote $zip"

# Installer: the icon is generated by build.rs into the cargo OUT_DIR; copy the newest one next to the script.
$ico = Get-ChildItem "target\release\build\winbend-*\out\winbend.ico" -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 1
if ($ico) { Copy-Item $ico.FullName "installer\winbend.ico" -Force }
$iscc = @(
  "${env:ProgramFiles(x86)}\Inno Setup 6\ISCC.exe",
  "$env:ProgramFiles\Inno Setup 6\ISCC.exe",
  "$env:LOCALAPPDATA\Programs\Inno Setup 6\ISCC.exe"
) | Where-Object { Test-Path $_ } | Select-Object -First 1
if (-not $iscc) { $cmd = Get-Command iscc -ErrorAction SilentlyContinue; if ($cmd) { $iscc = $cmd.Source } }
if ($iscc) {
  & $iscc "/DAppVersion=$version" "/DSourceDir=$root\target\release" "/Q" "installer\winbend.iss"
  if ($LASTEXITCODE -ne 0) { throw "Inno Setup failed" }
  Write-Host "wrote $root\dist\WinBend-Setup-$version.exe"
} else {
  Write-Host "Inno Setup 6 not found; skipped the installer (winget install JRSoftware.InnoSetup)."
}
